function audioInit(){if(!audioCtx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx=new AC();master=audioCtx.createGain();master.gain.value=.25;master.connect(audioCtx.destination);humGain=audioCtx.createGain();humGain.gain.value=0;humGain.connect(master);[53,80].forEach((f,i)=>{const o=audioCtx.createOscillator();o.type=i?'sine':'triangle';o.frequency.value=f;o.connect(humGain);o.start();});}if(!muted&&audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});}
function tone(freq,duration=.12,type='sine',volume=.2,delay=0,endFreq){if(muted||!audioCtx||audioCtx.state!=='running')return;const t=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(endFreq)o.frequency.exponentialRampToValueAtTime(endFreq,t+duration);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(volume,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(master);o.start(t);o.stop(t+duration+.02);}
function sound(kind){if(kind==='capture'){[330,440,660].forEach((f,i)=>tone(f,.15,'triangle',.3,i*.055));}if(kind==='dash')tone(180,.28,'sawtooth',.16,0,38);if(kind==='hit'){tone(70,.3,'sawtooth',.4,0,24);tone(120,.15,'square',.1);}if(kind==='missile')tone(500,.18,'square',.08,0,190);if(kind==='upgrade'){tone(330,.15,'triangle',.3);tone(660,.3,'triangle',.2,.1);}if(kind==='clear')[330,440,550,880].forEach((f,i)=>tone(f,.4,'triangle',.22,i*.13));}
