 for(let i=0;i<(level===6?0:62);i++){const row=Math.floor(i/10);let x=i===0?350:180+(i%10)*270+rand(-40,40),z=i===0?900:200+row*250+rand(-35,35);({x,z}=dryPosition(x,z));const type=level>2?(i%13===10?'gold':i%6===0?'cow':'human'):(i%11===9?'gold':i%3===1?'human':'cow');targets.push({id:newId(),x,y:surfaceY(x,z),z,base:surfaceY(x,z),type,phase:rand(0,TAU),dir:rand(0,TAU),lift:0,scan:0});}
 if(level===6){const crash=getStage(6).crashSite;for(let i=0;i<6;i++){const angle=i*TAU/6+.2,x=crash.x+Math.cos(angle)*125,z=crash.z+Math.sin(angle)*125;targets.push({id:newId(),x,z,y:surfaceY(x,z),base:surfaceY(x,z),type:'alien',phase:rand(0,TAU),dir:angle,lift:0,scan:0});}for(let i=0;i<16;i++){const angle=i*TAU/16,site=dryPosition(crash.x+Math.cos(angle)*(250+i%3*35),crash.z+Math.sin(angle)*(250+i%3*35));targets.push({id:newId(),...site,y:surfaceY(site.x,site.z),base:surfaceY(site.x,site.z),homeX:site.x,homeZ:site.z,type:'soldier',enemy:true,health:55,shoot:2+i*.2,phase:angle,dir:angle,lift:0,scan:0,walking:0});}}
