function buildMissionGoals(){
 if(missionType==='intercept')return [{label:'Neutralize '+(3+level)+' UFOs',detail:selectedAircraft==='sr71'?'Hold the primary action to designate contacts for friendly SAM strikes.':'Use your primary weapon to hunt down each contact.'},{label:'Prevent every escape',detail:'A contact that escapes with specimens ends the operation.'},{label:'Keep your aircraft intact',detail:'Finish the wave within the mission window.'}];
 const labels={cow:'Abduct cattle',human:'Abduct humans',ground:'Collect ground specimens',blackhawk:'Capture Black Hawks intact',fighter:'Capture fighters intact',sam:'Disable SAM batteries',sr71:'Capture the SR-71 Blackbird intact',alien:'Rescue the stranded alien crew'};const m=missions[level-1];return Object.keys(labels).filter(k=>m[k]).map(k=>({label:labels[k],detail:k==='alien'?'Bring all 6 crew aboard. Hold SPACE above the violet rescue markers.':'REQUIRED: '+m[k]})).concat(level===6?[{label:'Evade or fight the recovery troops',detail:'Evade rifle fire or hold F to disable troops. Your laser protects friendly crew.'}]:[]).concat({label:'Reach the extraction beacon',detail:'After all required goals, fly to the blue radar beacon.'});
}
function startLevel(){clearInput();state='briefing';screen('missionBrief');showFlight(false);$('dispatch').hidden=true;world.setStage(level);const c=getStage(level);$('missionBriefKicker').textContent='OPERATION '+String(level).padStart(2,'0')+' / '+c.name.toUpperCase();$('missionBriefTitle').textContent=missionType==='intercept'?'AIRSPACE DENIAL':missions[level-1].name;$('missionTerrain').textContent=c.biome+' — '+c.description;$('missionTime').textContent=durationText(missions[level-1].time*(mode==='explorer'?1.35:1))+' MISSION WINDOW';$('missionGoalList').replaceChildren();for(const [i,goal]of buildMissionGoals().entries()){const row=document.createElement('li');row.className='mission-goal';row.innerHTML='<span class="goal-number">'+String(i+1).padStart(2,'0')+'</span><div class="goal-copy"><strong>'+goal.label+'</strong><p>'+goal.detail+'</p></div>';$('missionGoalList').append(row);}$('footerStatus').textContent='MISSION BRIEFING / AWAITING LAUNCH';announce('Mission briefing. '+c.name+'. '+buildMissionGoals().map(g=>g.label+'. '+g.detail).join(' '));$('launchMission').focus({preventScroll:true});}
function durationText(seconds){const n=Math.max(0,Math.floor(seconds));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function renderMissionReport(id,won){const scoreDelta=Math.max(0,score-stageStartScore),airCaptures=(missionStats.blackhawk||0)+(missionStats.fighter||0)+(missionStats.sr71||0);const stats=[['Operation score',scoreDelta.toLocaleString()],['Objectives',missionProgress()+' / '+quota],[missionType==='intercept'?'UFOs neutralized':level===6?'Alien crew rescued':'Ground specimens',missionType==='intercept'?captures:level===6?(missionStats.alien||0):(missionStats.ground||0)],[missionType==='intercept'?'Damage taken':level===6?'Troops stopped':level===4?'SAMs disabled':'Aircraft captured',missionType==='intercept'?Math.round(stageDamageTaken):level===6?(missionStats.soldier||0):level===4?(missionStats.sam||0):airCaptures],['Elapsed',durationText(elapsed)],['Hull remaining',Math.round(player.hull)+'%']];$(id).replaceChildren();for(const [label,value]of stats){const item=document.createElement('div');item.className='report-stat';item.innerHTML='<span>'+label+'</span><strong>'+value+'</strong>';$(id).append(item);}$(id).setAttribute('aria-label',(won?'Passed':'Failed')+' mission report');}
