function localStorageSafe(key){try{return localStorage.getItem(key);}catch{return null;}}
const tutorial=[
 ['YOUR NIGHT. YOUR AIRSPACE.','Choose Abduction to pilot the UFO, or Intercept to hunt it as a fighter, Black Hawk, or SR-71. Six missions grow more demanding. Fill each objective, then fly to the blue extraction beacon.','01 / THE MISSION'],
 ['FLY IN THREE DIMENSIONS.','W / S fly forward and back. A / D steer, and the chase camera turns with you. Q climbs; E descends. Shift gives a burst of speed. On touch screens, use the flight pad and the altitude buttons.','02 / FLIGHT CONTROLS'],
 ['CATCH. CLIMB. ADAPT.','As the UFO, hold Space to acquire a target below you. Once tethered, keep flying: the beam follows and lifts it quickly. Climb above aircraft to capture them. Dogfighting pilots will resist; weaken them with F, your attack laser. Aircraft captures upgrade flight and weapons.','03 / ABDUCTION & COMBAT'],
 ['BREAK THE LOCK.','SAM radar acquires your ship before launching guided missiles and scrambling fighters and Black Hawks. Your automatic flares distract incoming missiles; Shift also breaks locks. Intercept pilots hold Space to attack. The SR-71 designates UFOs for ground-based SAM strikes. Use Help anytime.','04 / SURVIVE & UPGRADE']
];
