$('abductMode').onclick=()=>{missionType='abduct';$('abductMode').classList.add('selected');$('interceptMode').classList.remove('selected');$('aircraftChoice').hidden=true;};$('interceptMode').onclick=()=>{missionType='intercept';$('interceptMode').classList.add('selected');$('abductMode').classList.remove('selected');$('aircraftChoice').hidden=false;};
for(const type of ['fighter','blackhawk','sr71'])$(type+'Choice').onclick=()=>{selectedAircraft=type;for(const v of ['fighter','blackhawk','sr71'])$(v+'Choice').classList.toggle('selected',type===v);};
function pause(){if(state!=='playing')return;state='paused';clearInput();player.beam=false;screen('pauseScreen');$('dispatch').hidden=true;showFlight(false);$('resume').focus({preventScroll:true});$('footerStatus').textContent='HOLDING PATTERN';}
