function goMenu(){state='menu';clearInput();screen('menu');showFlight(false);$('dispatch').hidden=true;camera=900;$('best').textContent=pad(best);$('footerStatus').textContent='ALL SYSTEMS NOMINAL';$('start').focus({preventScroll:true});}
function help(){if(state==='help')return;previousState=state;clearInput();player.beam=false;state='help';screen('helpScreen');showFlight(false);$('dispatch').hidden=true;$('closeHelp').focus({preventScroll:true});}
function closeHelp(){state=previousState;if(state==='playing'){screen(null);showFlight(true);canvas.focus({preventScroll:true});}else if(state==='menu'){screen('menu');$('start').focus({preventScroll:true});}else if(state==='paused'){screen('pauseScreen');$('resume').focus({preventScroll:true});}else if(state==='briefing'){screen('missionBrief');$('launchMission').focus({preventScroll:true});}else if(state==='bay'){screen('bay');$('next').focus({preventScroll:true});}else{screen('end');$('again').focus({preventScroll:true});}}
