$('pause').onclick=()=>state==='playing'?pause():state==='paused'?resume():null;
function finish(won,reason){lastEndWon=won;renderMissionReport('endReport',won);state='end';clearInput();player.beam=false;showFlight(false);screen('end');$('dispatch').hidden=true;$('endKicker').textContent=won?'PROTOCOL COMPLETE / EARTH REMAINS CONFUSED':'MISSION DEBRIEF / SIGNAL TERMINATED';$('endTitle').innerHTML=won?'NIGHT SHIFT.<br><em>COMPLETE.</em>':'CONTACT<br><em>LOST.</em>';$('endReason').textContent=reason;$('again').textContent=won?'NEW OPERATION ↗':'RETRY OPERATION ↗';$('finalScore').textContent=pad(score);$('finalCaptures').textContent=totalCaptures;$('finalCombo').textContent=Math.max(1,bestCombo)+'×';if(score>best){best=score;hasNewRecord=true;save('ap-best-v1',best);}$('newRecord').hidden=!hasNewRecord;$('footerStatus').textContent=won?'MISSION ACCOMPLISHED':'AWAITING NEW PILOT';announce((won?'Victory. ':'Mission ended. ')+reason+' Final score '+score);$('again').focus({preventScroll:true});if(won)sound('clear');}
function sectorComplete(){if(state!=='playing')return;player.beam=false;clearInput();const timeBonus=Math.ceil(remaining)*10;score+=timeBonus;credits+=100+level*30;completedOperations++;sound('clear');renderMissionReport('missionReport',true);if(level===missions.length){finish(true,missionType==='intercept'?`Airspace secure. Operations completed: ${completedOperations}. UFOs neutralized: ${totalCaptures}.`:`Protocol complete. Operations completed: ${completedOperations}. Contacts secured: ${totalCaptures}.`);return;}state='bay';showFlight(false);screen('bay');$('dispatch').hidden=true;$('bayKicker').textContent=getStage(level).name.toUpperCase()+' / MISSION PASSED';$('bayTitle').textContent='OPERATION SECURED.';$('baySummary').textContent=(missionType==='intercept'?'AIRSPACE DENIAL':missions[level-1].name)+' complete. +'+timeBonus.toLocaleString()+' time bonus. Next deployment: '+getStage(level+1).name+'.';player.hull=Math.min(100,player.hull+30);player.shield=player.maxShield;$('refit').open=false;renderUpgrades();$('next').focus({preventScroll:true});announce('Mission passed. Review your stats, then review the next mission briefing. Ship refit is optional.');}
const upgradeInfo=[{id:'beam',symbol:'⌁',name:'Tractor / targeting',desc:'25% faster tether or weapon lock.',base:75},{id:'shield',symbol:'◈',name:'Shield matrix',desc:'+25 shield capacity per level.',base:85},{id:'engine',symbol:'↗',name:'Ion thrusters',desc:'+12% speed. Dash recharges faster.',base:75},{id:'repair',symbol:'✚',name:'Hull repair',desc:'Restore 40 hull integrity.',base:45}];
function renderUpgrades(){$('credits').textContent='¢ '+credits;$('upgrades').replaceChildren();upgradeInfo.forEach(info=>{const lv=upgrades[info.id]||0,price=info.base+lv*50,max=info.id!=='repair'&&lv>=3;const button=document.createElement('button');button.className='upgrade';button.title=info.desc;button.disabled=max||credits<price||(info.id==='repair'&&player.hull>=100);button.innerHTML=`<span class="symbol" aria-hidden="true">${info.symbol}</span><span class="level">${info.id==='repair'?Math.ceil(player.hull)+'% HULL':lv+'/3'}</span><strong>${info.name}</strong><p>${info.desc}</p><span class="price">${max?'MAXIMUM':info.id==='repair'&&player.hull>=100?'HULL FULL':'¢ '+price+' · INSTALL'}</span>`;button.onclick=()=>buy(info.id);$('upgrades').append(button);});}
function buy(id){if(state!=='bay')return;const info=upgradeInfo.find(i=>i.id===id);if(!info)return;const lv=upgrades[id]||0,price=info.base+lv*50;if(credits<price||(id!=='repair'&&lv>=3)||(id==='repair'&&player.hull>=100))return;credits-=price;if(id==='repair')player.hull=Math.min(100,player.hull+40);else upgrades[id]++;if(id==='shield'){player.maxShield=60+upgrades.shield*25;player.shield=player.maxShield;}sound('upgrade');renderUpgrades();announce(info.name+' installed. '+credits+' credits remaining.');}
