function dash(){if(state!=='playing'||player.dashCooldown>0)return;let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x,z=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;if(Math.hypot(x,z)<.1){x=Math.sin(player.heading);z=-Math.cos(player.heading);}const mag=Math.hypot(x,z);player.dashX=world.cameraMode==='chase'?-Math.sin(player.heading):x/mag;player.dashZ=world.cameraMode==='chase'?-Math.cos(player.heading):z/mag;player.dash=.32;player.invincible=.55;player.dashCooldown=3.5-upgrades.engine*.45;missiles.filter(m=>m.hostile).forEach(m=>m.homing=false);threat=Math.max(0,threat-30);burst(player.x,player.y,18,'#ffbb75',130,player.z);sound('dash');}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(e.target instanceof HTMLInputElement)return;if(k==='m'&&!e.repeat){$('sound').click();return;}if((k==='p'||k==='escape')&&!e.repeat){e.preventDefault();if(state==='playing')pause();else if(state==='paused')resume();else if(state==='help')closeHelp();return;}if(state!=='playing')return;if([' ','arrowup','arrowdown','arrowleft','arrowright','shift','w','a','s','d','q','e','f'].includes(k)){e.preventDefault();keys.add(k);if(k==='shift'&&!e.repeat)dash();}});
