 for(let i=missiles.length-1;i>=0&&state==='playing';i--){const m=missiles[i];m.age+=dt;m.life-=dt;const target=m.hostile?player:(missionType==='abduct'?[...aircraft,...targets.filter(t=>t.enemy)]:aliens).find(a=>a.id===m.targetId);if(target&&m.homing){const d=combatDistance(m,target)||1,sp=360;const t=1-Math.exp(-dt*1.5);m.vx=lerp(m.vx,(target.x-m.x)/d*sp,t);m.vy=lerp(m.vy,(target.y-m.y)/d*sp,t);m.vz=lerp(m.vz,(target.z-m.z)/d*sp,t);}m.x+=m.vx*dt;m.y+=m.vy*dt;m.z+=m.vz*dt;if(!m.rifle&&Math.random()<dt*50)particles.push({x:m.x,y:m.y,z:m.z,vx:0,vy:10,vz:0,life:.7,max:.7,size:3,color:'#ffb16e'});if(target&&combatDistance(m,target)<(m.rifle?20:35)){missiles.splice(i,1);if(m.hostile)hit(m.damage);else{target.health-=m.damage;if(target.health<=0){if(missionType==='abduct'){if(target.type==='soldier')stopTroop(target);else{aircraft=aircraft.filter(a=>a!==target);score+=400;credits+=20;}}else{aliens=aliens.filter(a=>a!==target);captures++;totalCaptures++;score+=1400;credits+=60;}burst(target.x,target.y,30,'#ffb16e',130,target.z);checkObjectives();}}}else if(m.life<=0||m.y>surfaceY(m.x,m.z))missiles.splice(i,1);}
