function lerpAngle(a,b,t){return a+Math.atan2(Math.sin(b-a),Math.cos(b-a))*Math.min(t,1);}
function updateHud(){$('sector').innerHTML=String(level).padStart(2,'0')+' <small>/ '+String(missions.length).padStart(2,'0')+'</small>';$('location').textContent=getStage(level).name.toUpperCase();$('quota').textContent=missionProgress()+' / '+quota;$('quotaBar').style.width=clamp(missionProgress()/quota*100,0,100)+'%';const secondsLeft=Math.ceil(Math.max(0,remaining));$('time').textContent=String(Math.floor(secondsLeft/60)).padStart(2,'0')+':'+String(secondsLeft%60).padStart(2,'0');$('score').textContent=pad(score);$('combo').textContent=missionType==='intercept'?selectedAircraft.toUpperCase():combo>1?combo+'× CHAIN • LASER MK '+player.weapon:'LASER MK '+player.weapon+' • TECH '+player.tech;$('hullBar').style.width=player.hull+'%';$('shieldBar').style.width=player.shield/player.maxShield*100+'%';$('dashStatus').textContent=player.dashCooldown>0?'BOOST '+player.dashCooldown.toFixed(1)+'s':'BOOST READY';$('threatBar').style.width=threat+'%';$('threatLabel').textContent=threat>75?'SAM ACQUIRING':threat>25?'RADAR TRACKING':'RADAR SEARCHING';$('objective').textContent=objectiveText();$('altitude').textContent=Math.round(surfaceY(player.x,player.z)-player.y)+'m AGL • '+Math.round(Math.hypot(player.vx,player.vz))+' SPD';$('flareStatus').textContent=flareCooldown>0?'FLARES '+Math.ceil(flareCooldown)+'s':'AUTO FLARES READY';drawRadar();}
function drawRadar(){
 const c=$('radar'),r=c.getContext('2d'),size=240,center=120,radius=109,range=1050,heading=player.heading||0;r.clearRect(0,0,size,size);r.save();r.beginPath();r.arc(center,center,radius,0,TAU);r.clip();const bg=r.createRadialGradient(center,center,8,center,center,radius);bg.addColorStop(0,'#0c293355');bg.addColorStop(1,'#07141d77');r.fillStyle=bg;r.fillRect(0,0,size,size);
 r.strokeStyle='#a0e4d227';r.lineWidth=1;for(const f of [.33,.66,1]){r.beginPath();r.arc(center,center,radius*f,0,TAU);r.stroke();}for(let i=0;i<8;i++){const a=i*TAU/8;r.beginPath();r.moveTo(center,center);r.lineTo(center+Math.cos(a)*radius,center+Math.sin(a)*radius);r.stroke();}
 const sweep=clock*.65;r.fillStyle='#9bffda13';r.beginPath();r.moveTo(center,center);r.arc(center,center,radius,sweep-.6,sweep);r.closePath();r.fill();r.strokeStyle='#a0ffda50';r.beginPath();r.moveTo(center,center);r.lineTo(center+Math.cos(sweep)*radius,center+Math.sin(sweep)*radius);r.stroke();
 function blip(a,kind){const dx=a.x-player.x,dz=(a.z??900)-player.z,d=Math.hypot(dx,dz),edge=d>range;if(edge&&kind==='ground')return;const scale=radius/(edge?d*1.09:range),x=center+(dx*Math.cos(heading)-dz*Math.sin(heading))*scale,y=center+(dx*Math.sin(heading)+dz*Math.cos(heading))*scale;r.save();r.translate(x,y);r.lineWidth=1.6;const color=kind==='missile'?'#ff698f':kind==='bogey'?'#ffb86f':kind==='blackbird'?'#c5a0ff':kind==='sam'?'#ff7689':kind==='extract'?'#84d2ff':kind==='crew'?'#cfadff':kind==='troop'?'#ff698f':'#a1f9cb';r.strokeStyle=r.fillStyle=color;
 if(edge){r.rotate(Math.atan2(y-center,x-center));r.beginPath();r.moveTo(5,0);r.lineTo(-3,-4);r.lineTo(-3,4);r.closePath();r.stroke();}
 else if(kind==='bogey'||kind==='blackbird'){r.beginPath();r.moveTo(0,-5);r.lineTo(-4,4);r.lineTo(0,2);r.lineTo(4,4);r.closePath();r.stroke();}
 else if(kind==='missile'){if(reduced||Math.sin(clock*10)>-.35){r.beginPath();r.moveTo(0,-4);r.lineTo(3,3);r.lineTo(-3,3);r.closePath();r.fill();r.globalAlpha=.6;r.beginPath();r.moveTo(0,4);r.lineTo(0,9);r.stroke();}}
 else if(kind==='sam'){r.rotate(Math.PI/4);r.strokeRect(-3,-3,6,6);}
 else if(kind==='crew'){r.beginPath();r.arc(0,0,3.5,0,TAU);r.stroke();r.beginPath();r.moveTo(-5,0);r.lineTo(5,0);r.moveTo(0,-5);r.lineTo(0,5);r.stroke();}
 else if(kind==='troop'){r.strokeRect(-2.5,-2.5,5,5);}
 else if(kind==='extract'){r.beginPath();r.arc(0,0,5,0,TAU);r.stroke();r.beginPath();r.moveTo(-7,0);r.lineTo(7,0);r.moveTo(0,-7);r.lineTo(0,7);r.stroke();}
 else {r.fillRect(-1.6,-1.6,3.2,3.2);}r.restore();}
 targets.forEach(t=>blip(t,t.type==='alien'?'crew':t.enemy?'troop':'ground'));lights.filter(l=>l.health>0).forEach(l=>blip(l,'sam'));aircraft.forEach(a=>blip(a,a.type==='sr71'?'blackbird':'bogey'));aliens.forEach(a=>blip(a,'bogey'));missiles.forEach(m=>blip(m,'missile'));blip(getStage(level).extract,'extract');
 r.fillStyle='#e1fff0';r.beginPath();r.moveTo(center,center-8);r.lineTo(center-5,center+5);r.lineTo(center,center+2);r.lineTo(center+5,center+5);r.closePath();r.fill();r.restore();r.strokeStyle='#a6fadd88';r.lineWidth=1.5;r.beginPath();r.arc(center,center,radius,0,TAU);r.stroke();r.font='12px Arial';r.textAlign='center';r.fillStyle='#c4ecdd';r.fillText('TACTICAL • 1 KM',center,233);
}
function effects(dt){particles=particles.filter(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=(p.vz||0)*dt;return p.life>0;});popups=popups.filter(p=>{p.life-=dt;p.y-=dt*28;return p.life>0;});ghosts=ghosts.filter(p=>{p.life-=dt;return p.life>0;});shake=Math.max(0,shake-dt*35);if(dispatchTimer>0){dispatchTimer-=dt;if(dispatchTimer<=0)$('dispatch').hidden=true;}}
function drawCodeRain(){if(clock-rainStamp<.085)return;rainStamp=clock;const r=shell.getBoundingClientRect(),w=Math.round(r.width),h=Math.round(r.height);if(rainCanvas.width!==w||rainCanvas.height!==h){rainCanvas.width=w;rainCanvas.height=h;}rainCtx.clearRect(0,0,w,h);const menu=state!=='playing',columns=Math.floor(w/29);rainCtx.font='13px Courier New';rainCtx.textAlign='center';for(let c=0;c<columns;c++){if(!menu&&c>1&&c<columns-2)continue;const speed=reduced?0:clock*22;const head=((speed+c*83)%(h+280))-60;for(let row=0;row<12;row++){const y=head-row*18;if(y<0||y>h)continue;const v=Math.sin(c*119+row*37+Math.floor((reduced?0:clock)*.6))*10000;const char='01ABCDEF<>'.charAt(Math.abs(Math.floor(v))%10);rainCtx.fillStyle=c%7===0?'#ad79ff':'#00ff66';rainCtx.globalAlpha=(menu?.26:.075)*(1-row/13);rainCtx.fillText(char,17+c*29,y);}}rainCtx.globalAlpha=1;}
function render(dt){drawCodeRain();const menu=state==='menu'||state==='tutorial'||state==='briefing'||state==='help'&&(previousState==='menu'||previousState==='briefing');const sceneLevel=state==='briefing'||state==='help'&&previousState==='briefing'?level:menu?selectedStage:level;world.draw({level:sceneLevel,player,playerType:playerType(),menu,time:clock,dt,targets,lights:lights.filter(l=>l.health>0),aircraft,missiles,aliens,particles,laser,reduced,hull:player.hull??100,extraction,beamAnchor:targets.find(t=>t.lift)||aircraft.find(a=>a.capture>0)});$('radar').hidden=state!=='playing';$('radarLegend').hidden=state!=='playing';$('objective').hidden=state!=='playing';$('telemetry').hidden=state!=='playing';$('flightReticle').hidden=state!=='playing';$('headingReadout').textContent='HDG '+String(Math.round(((player.heading||0)*-180/Math.PI+360)%360)).padStart(3,'0');drawMarkers();}
function drawMarkers(){const layer=$('markers');layer.replaceChildren();if(state!=='playing')return;const near=targets.filter(t=>!t.lift&&flatDistance(t,player)<(t.type==='alien'?1800:800)).sort((a,b)=>flatDistance(a,player)-flatDistance(b,player)).slice(0,10);const list=[...targets.filter(t=>t.lift).map(t=>({...t,label:t.type==='alien'?'RESCUING CREW':'TRACTOR LOCK'})),...aircraft.filter(a=>a.capture>0).map(a=>({...a,label:'RESISTING '+Math.round(a.capture/(a.type==='sr71'?2.5:a.type==='fighter'?1.9:1.5)*100)+'%'})),...aliens.map(a=>({...a,label:'UFO • '+Math.ceil(a.health/120*100)+'%'})),...near.map(t=>({...t,bracket:true,label:(t.type==='alien'?'RESCUE CREW':t.enemy?'HOSTILE':t.type==='human'?'HUMAN':'CATTLE')+' · '+Math.round(flatDistance(t,player))+'m'}))];if(level===6&&missionType==='abduct'&&!extraction){const c=getStage(6).crashSite;list.push({...c,y:surfaceY(c.x,c.z)-45,label:'CRASH SITE • '+(missionStats.alien||0)+'/6 RESCUED'});}if(extraction){const e=getStage(level).extract;list.push({x:e.x,y:surfaceY(e.x,e.z)-40,z:e.z,label:'EXTRACTION'});}const placed=[];for(const t of list){const p=world.project({...t,y:t.y-(t.bracket?9:0)});if(!p.visible)continue;if(t.bracket&&p.x>world.width-235&&p.y>world.height-260)continue;if(t.bracket&&placed.some(q=>Math.abs(q.x-p.x)<100&&Math.abs(q.y-p.y)<45))continue;placed.push(p);const d=document.createElement('span');d.className=t.bracket?'target-bracket':'target-marker';d.style.left=p.x+'px';d.style.top=(p.y-(t.bracket?0:45))+'px';if(t.bracket){d.dataset.label=t.label;if(t.enemy)d.classList.add('hostile');if(t.type==='alien')d.classList.add('rescue');}else d.textContent=t.label;layer.append(d);}}
function frame(now){const dt=Math.min((now-last)/1000||0,.04);last=now;clock+=dt;if(state==='playing'){update(dt);effects(dt);}if(humGain&&audioCtx)humGain.gain.setTargetAtTime(!muted&&state==='playing'?(player.beam?.06:.018):0,audioCtx.currentTime,.12);render(dt);requestAnimationFrame(frame);}
